<script setup lang="ts">import{reactive}from'vue';import{useRouter}from'vue-router';import{useAuthStore}from'@/stores/auth';const form=reactive({username:'',password:''});const router=useRouter();const auth=useAuthStore();async function submit(){await auth.login(form.username,form.password);router.push('/')}</script>
<template><div class="login"><el-card class="card"><h2>需求与版本管理系统</h2><el-form @submit.prevent="submit"><el-form-item><el-input v-model="form.username" placeholder="用户名"/></el-form-item><el-form-item><el-input v-model="form.password" type="password" show-password placeholder="密码"/></el-form-item><el-button type="primary" style="width:100%" @click="submit">登录</el-button></el-form></el-card></div></template>
<style scoped>.login{min-height:100vh;display:grid;place-items:center;background:linear-gradient(135deg,#eaf4ff,#f8fbff)}.card{width:min(420px,92vw)}</style>
